{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "template": {
      "type": "string",
      "description": "The full reconstructed transcript text with specific niche details replaced by fill-in-the-blank placeholders formatted exactly as [[ description of what to enter ]] inside the string."
    },
    "stage": {
      "type": "string",
      "enum": ["TOFU", "MOFU", "BOFU"],
      "description": "The marketing funnel stage of the script."
    },
    "cta": {
      "type": "string",
      "enum": ["Follow", "Freebie", "Offer"],
      "description": "The type of call to action used at the end of the script."
    },
    "type": {
      "type": "string",
      "enum": ["Simple", "Complex"],
      "description": "The structural complexity rating of the script."
    },
    "perspective": {
      "type": "string",
      "enum": ["Educational", "Storytelling"],
      "description": "The delivery style or narrative angle of the script."
    }
  },
  "required": ["template", "stage", "cta", "type", "perspective"],
  "additionalProperties": false
}

parameters.jsCode:
const rawInput = $input.first().json.chatInput;

const urlRegex = /(https?:\/\/[^\s]+)/g;
const match = rawInput.match(urlRegex);

if (!match) {
    throw new Error("No valid URL detected.");
}

let cleanUrl = match[0];

try {
    const urlObj = new URL(cleanUrl);
    urlObj.search = "";
    cleanUrl = urlObj.toString();

    if (cleanUrl.endsWith('/')) {
        cleanUrl = cleanUrl.slice(0, -1);
    }
} catch (e) {
    cleanUrl = cleanUrl.split('?')[0];
    if (cleanUrl.endsWith('/')) {
        cleanUrl = cleanUrl.slice(0, -1);
    }
}

const supportedPlatforms = ['instagram', 'tiktok', 'youtube'];
const isSupported = supportedPlatforms.some(platform => cleanUrl.toLowerCase().includes(platform));

if (!isSupported) {
    throw new Error("No supported platform URL detected.");
}

return [{ json: { url: cleanUrl } }];

const llmOutput = $json.output;

const originalUrl = $('URL').first().json.url;

let templateText = llmOutput.template || "";

templateText = templateText.replace(/\[\[\s*(.*?)\s*\]\]/g, "{{ $1 }}");

const sentenceEndRegex = /([.?!]+|\.\.\.|\…)\s*/g;

const matches = templateText.match(sentenceEndRegex) || [];
let processedTemplate = templateText;

if (matches.length > 1) {
    processedTemplate = templateText.replace(sentenceEndRegex, (match, p1) => {
        return p1 + "\n\n";
    });
}

let pageTitle = "Template";
const firstMatch = templateText.match(/([.?!]+|\.\.\.|\…)/g);

if (firstMatch) {
    const firstPunctuationIndex = templateText.indexOf(firstMatch[0]) + firstMatch[0].length;
    pageTitle = templateText.substring(0, firstPunctuationIndex).trim();
} else {
    pageTitle = templateText.trim();
}

pageTitle = pageTitle.replace(/\r?\n|\r/g, " ");

return {
    json: {
        title: pageTitle,
        template: processedTemplate.trim(),
        url: originalUrl,
        stage: llmOutput.stage,
        cta: llmOutput.cta,
        type: llmOutput.type,
        perspective: llmOutput.perspective
    }
};

parameters.jsonBody:
={{ {
  "children": [
    {
      "object": "block",
      "type": "code",
      "code": {
        "rich_text": (() => {
          const template = $('JSON').first().json.template || "";

          // Using RegExp constructor protects the double closing braces from crashing n8n
          const regex = new RegExp('(\\{\\{[\\s\\S]*?\\}' + '})', 'g');
          const parts = template.split(regex);
          const richText = [];

          parts.forEach(part => {
            if (!part) return;

            if (part.startsWith('{{') && part.endsWith('}' + '}')) {
              richText.push({
                "type": "text",
                "text": { "content": part },
                "annotations": { "bold": true }
              });
            } else {
              const chunks = part.match(/[\s\S]{1,2000}/g) || [];
              chunks.forEach(chunk => {
                richText.push({
                  "type": "text",
                  "text": { "content": chunk }
                });
              });
            }
          });

          return richText;
        })(),
        "language": "plain text"
      }
    }
  ]
} }}

